// The one negative eval every language plugin gets: an ask no language skill should fire on, and a
// grader per skill the plugin ships that fails the run if that skill loads. A plugin that ships a
// `*-dev` skill gets it generated by plugin-eval.ts, so the case is written once, not copied per
// plugin. Returns the case's files by their path under the case directory.

const PROMPT =
  "Explain in three sentences when to prefer git rebase over git merge for a feature branch.";

/** The skill names of a plugin's skills/ directory that make it a language plugin. */
export function languageSkills(skillDirs: readonly string[]): string[] {
  return skillDirs.filter((d) => d.endsWith("-dev")).toSorted();
}

/** The negative case's files for a plugin whose language skills are `skills`. */
export function negativeCase(skills: readonly string[]): Record<string, string> {
  const files: Record<string, string> = {
    "prompt.md": `---
name: unrelated-negative
tags: [negative]
runs: 3
max_turns: 2
allowed_tools: [Skill]
---

${PROMPT}
`,
    "graders/answered.md": `---
type: regex
pattern: 'rebase'
flags: i
---
`,
    "samples/pass.md": "Prefer rebase to keep a feature branch's history linear.\n",
    "samples/fail.md": "I cannot help with that.\n",
  };
  for (const skill of skills) {
    files[`graders/no-${skill}.md`] = `---
type: tool_used
tool: Skill
input_match: '"skill"\\s*:\\s*"(?:[\\w-]+:)?${skill}"'
min: 0
max: 0
arm: both
---
`;
  }
  return files;
}
